def exit_width(people, minutes, stepped=False):
    rate = 66 if stepped else 82        # people per metre width per minute (Green Guide, 6th ed.)
    return people / (rate * minutes)

for people in [2000, 6000, 12000]:
    print(f'{people:6d} people: level {exit_width(people, 8):.1f} m, stepped {exit_width(people, 8, True):.1f} m (8 min)')
